-- 1779718907_0001 (up)
-- Initial schema: subjects and enames.
--
-- Conventions:
--   - Plural table names, singular column names; FK pattern <singular>_id -> <plural>.id.
--   - UUIDv7 generated by the application (`v7()` in Node, `Uuid::now_v7()` in Rust),
--     not by PostgreSQL — no DEFAULT on `id`.
--   - `created_at` is supplied by the application from the event-log event timestamp,
--     not `DEFAULT now()`, so the SQL projection remains deterministically reconstructible
--     by log replay.
--   - Format-level validation of `name_part` lives in the application (Zod). The
--     database enforces only invariants expected to hold across all future format
--     evolutions: length, and the broadest allowed character set (lowercase letters,
--     digits, hyphen) — digits are already included here in anticipation of
--     organization enames. Finer rules (hyphen placement, etc.) live in Zod.

CREATE TABLE subjects (
  id          UUID        PRIMARY KEY,
  kind        TEXT        NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL,

  CONSTRAINT subjects_kind_allowed CHECK (kind IN ('person'))
);

CREATE TABLE enames (
  id           UUID        PRIMARY KEY,
  subject_id   UUID        NOT NULL REFERENCES subjects (id),
  name_part    TEXT        NOT NULL,
  number_part  BIGINT      NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL,

  CONSTRAINT enames_name_part_length     CHECK (length(name_part) BETWEEN 1 AND 50),
  CONSTRAINT enames_name_part_charset    CHECK (name_part ~ '^[a-z0-9-]+$'),
  CONSTRAINT enames_number_part_range    CHECK (number_part BETWEEN 1 AND 999_999_999_999),
  UNIQUE (name_part, number_part)
);

CREATE INDEX enames_subject_id_idx ON enames (subject_id);
